<?php
namespace ETG\DynamicFilterSEOBridge\Runtime;
use ETG\DynamicFilterSEOBridge\Compatibility;use ETG\DynamicFilterSEOBridge\Config\Configuration;use ETG\DynamicFilterSEOBridge\Config\ProfileRegistry;
final class Readiness{
private $compatibility;private $config;private $profiles;public function __construct(Compatibility $compatibility,Configuration $config,ProfileRegistry $profiles){$this->compatibility=$compatibility;$this->config=$config;$this->profiles=$profiles;}
public function report():array{$compat=$this->compatibility->report();$required=array('jet_smart_filters','jet_engine','rank_math','wpml','elementor');$publicationRequiresThemeBuilder=false;$darkValidationProfiles=array();foreach($this->profiles->all() as $profileId=>$profile){if(!empty($profile['publication']['require_elementor_content'])){$publicationRequiresThemeBuilder=true;$darkValidationProfiles[]=(string)$profileId;}}if($publicationRequiresThemeBuilder){$required[]='elementor_pro';}$missing=array();foreach(array_values(array_unique($required)) as $dependency){if(empty($compat[$dependency])){$missing[]=$dependency;}}$missingCapabilities=array();foreach((array)($compat['capabilities']??array()) as $name=>$ok){if(!$ok){$missingCapabilities[]=$name;}}$configErrors=array_merge($this->config->validationErrors(),$this->profiles->validationErrors());$runtimeChecks=array();$pending=!function_exists('did_action')||did_action('init')<1;if(!$pending){foreach($this->profiles->all() as $profileId=>$profile){if(empty($profile['enabled'])){continue;}$postTypes=(array)($profile['post_types']??array());if(function_exists('post_type_exists')){foreach($postTypes as $postType){$runtimeChecks['post_type:'.$profileId.':'.$postType]=post_type_exists($postType);}}foreach(array_keys((array)($profile['taxonomy_rules']??array())) as $taxonomy){if(function_exists('taxonomy_exists')){$runtimeChecks['taxonomy:'.$profileId.':'.$taxonomy]=taxonomy_exists($taxonomy);}if($postTypes&&function_exists('get_taxonomy')){$object=get_taxonomy($taxonomy);$objectTypes=is_object($object)&&isset($object->object_type)?(array)$object->object_type:array();$runtimeChecks['taxonomy_relation:'.$profileId.':'.$taxonomy]=(bool)array_intersect($postTypes,$objectTypes);}}}}$failedRuntime=array();foreach($runtimeChecks as $name=>$ok){if(!$ok){$failedRuntime[]=$name;}}if(!$this->config->enabled()){$status='inactive';}elseif($missing||$missingCapabilities||$configErrors||$pending||$failedRuntime){$status='degraded';}else{$status='ready';}return array('contract'=>'etg.dfsb.readiness.v4','status'=>$status,'configuration_revision'=>$this->config->revision(),'profile_count'=>count($this->profiles->all()),'enabled_profiles'=>array_values(array_keys(array_filter($this->profiles->all(),static function($profile){return !empty($profile['enabled']);}))),'dark_validation_profiles'=>array_values(array_unique($darkValidationProfiles)),'publication_requires_elementor_pro'=>$publicationRequiresThemeBuilder,'missing_dependencies'=>$missing,'missing_capabilities'=>$missingCapabilities,'configuration_errors'=>array_values(array_unique($configErrors)),'runtime_checks_pending'=>$pending,'runtime_checks'=>$runtimeChecks,'failed_runtime_checks'=>$failedRuntime,'compatibility'=>$compat);}
public function ready():bool{$report=$this->report();return 'ready'===$report['status'];}}
